INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'1', N'Images\Garfield.png', N'Garfield The Movie', '2024-04-12', N'Garfield, the world-famous, Monday-hating, lasagne-loving indoor cat, is about to have a wild outdoor adventure! After an unexpected reunion with his long-lost father - scruffy street cat Vic - Garfield and his canine friend Odie are forced from their perfectly pampered lives into joining Vic in a hilarious, high-stakes heist.', N'2 Hours', N'Comedy', N'English', N'2', 20.0, '2024-11-12T11:11:11');
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'11', N'Images\fantastic4.png', N'The Fantastic 4', '2024-07-24', N'Transported to an alternate universe, four young outsiders gain superhuman powers as they alter their physical form in shocking ways.', N'1 Hour 51 Minutes', N'Adventure', N'English', N'4', 20.0, '2024-12-11T11:11:12');
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'12', N'Images\wildrobot.png', N'The Wild Robot', '2024-09-19', N'When Rozzum 7134 (Roz for short), a robot designed for a futuristic urban world, finds herself washed ashore on a deserted island, a tale of survival and discovery begins when she becomes the unexpected protector to an orphaned gosling, which she names Brightbill. Together they struggle to survive the harsh environment, but only succeed with the help of a close-knit group of misfit animals, who become first friends, then family. Ultimately Roz and company save the island from a robotic invasion by Roz`s manufacturer, looking to bring her back to civilisation by any means necessary. In the process she becomes something much more than she was programmed to be, a wild robot.', N'2 Hours 22 Minutes', N'Adventure', N'English', N'2', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'13', N'Images\alien.png', N'Alien Romulus', '2024-08-15', N'The sci-fi horror is directed by Fede Alvarez. It is a standalone instalment in the "Aliens" franchise and the ninth film overall.', N'1 Hours 58 Minutes', N'Horror', N'English', N'3', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'14', N'Images\article20.png', N'Article 20', '2024-06-04', N'The story of presecutor Han Ming who is involved in a difficult case where the intentional injury of people is turned into a legitimate defense.', N'2 Hours 21 Minutes', N'Drama', N'Mandarin', N'1', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'15', N'Images\deadpool.png', N'Deadpool & Wolverine', '2024-07-18', N'Wade Wilson aka Deadpool returns in the third instalment of the film, this time with Wolverine aka James "Logan" Howlett and Elektra.', N'1 Hour 41 Minutes', N'Comedy', N'English', N'4', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'16', N'Images\insideout.png', N'Inside Out 2', '2024-06-13', N'The mind of newly minted teenager Riley is undergoing a sudden demolition to make room for something entirely unexpected: new Emotions! Joy, Sadness, Anger, Fear and Disgust, who`ve long been running a successful operation by all accounts, aren`t sure how to feel when Anxiety shows up. And it looks like she`s not alone.', N'2 Hours 03 Minutes', N'Animation', N'English', N'2', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'17', N'Images\if.png', N'IF', '2024-05-16', N'A young girl goes through a difficult experience and then begins to see everyone`s imaginary friends who have been left behind as their real-life friends have grown up.', N'1 Hour 47 Minutes', N'Drama', N'English', N'5', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'18', N'Images\tarot.png', N'Tarot', '2024-06-01', N'When a group of friends recklessly violates the sacred rule of Tarot readings they unknowingly unleash an unspeakable evil trapped within the cursed cards. One by one, they come face to face with fate and end up in a race against death.', N'1 Hour 32 Minutes', N'Horror', N'English', N'3', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'2', N'Images\despicableme.png', N'Despicable Me 4', '2024-07-04', N'Gru, the world`s favourite supervillain-turned-Anti-Villain League-agent, has just welcomed a new member to his growing family - consisting of his wife Lucy, their three adopted daughters Margo, Edith and Agnes, and their baby Gru Jr. The family is forced to go on the run when they become targeted by escaped criminal Maxime Le Mal and his femme fatale girlfriend Valentina.', N'2 Hours 06 Minutes', N'Animation', N'English', N'5', 20.0, '2024-11-12T11:11:11');
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'200', N'Images\GodzillaXKong.png', N'Godzilla X Kong: The New Empire', '2024-03-11', N'The almighty Kong and the fearsome Godzilla are pit against a colossal undiscovered threat hidden within our world, challenging their very existence - and our own. The epic new film will delve further into the histories of these Titans, their origins and the mysteries of Skull Island and beyond, while uncovering the mythic battle that helped forge these extraordinary beings and tied them to humankind forever.', N'1 Hour 55 Minutes', N'Action', N'English', N'1', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'3', N'Images\KungFuPanda.png', N'KungFu Panda 4', '2024-01-20', N'The Dragon Warrior is back, and he''s about to embark to face the most threatening enemy he''s ever had to battle. Po leaves the Valley of Peace to go to the big city, where the unexpected personification of evil will already be waiting for him. A new villain, called The Chameleon, is in town, and the Dragon Warrior''s new adversary is not someone he can mess around with.', N'1 Hour 35 Minutes', N'Action', N'English', N'3', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'4', N'Images\nowayup.png', N'No Way Up', '2024-02-25', N'Characters from different backgrounds are thrown together when the plane they''re travelling on crashes into the Pacific Ocean. A nightmare fight for survival ensues with the air supply running out and dangers creeping in from all sides.', N'2 Hours 30 Minutes', N'Horror', N'English', N'5', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'60', N'Images\MoneyNotEnough.png', N'Money Not Enough 3', '2024-02-08', N'Ah Huang, Ah Qiang and Ah Hui have been friends for as long as they can remember. When Ah Huang`s mounting debts drive him to desperate measures, Ah Qiang and Ah Hui agree to lend him money. He uses the money to build an illegal business. Even after the business become successful, he refuses to repay the money to his friends. However, when the business collapses, Ah Huang is forced to question everything as his family, friendships, and remaining money are all threatened.', N'2 Hours 18 Minutes', N'Comedy', N'English', N'5', 20.0, '2024-11-12T11:11:50');
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'7', N'Images\Imaginary.png', N'Imaginary', '2024-03-08', N'From Blumhouse, the genre-defining masterminds behind FIVE NIGHTS AT FREDDY''S and M3GAN, comes an original horror that taps into the innocence of imaginary friends -- and begs the question: Are they really figments of childhood imagination or is something more terrifying lying just beneath? When Jessica (DeWanda Wise) moves back into her childhood home with her family, her youngest stepdaughter Alice (Pyper Braun) develops an eerie attachment to a stuffed bear named Chauncey she finds in the basement. Alice starts playing games with Chauncey that begin playful and become increasingly sinister. As Alice''s behavior becomes more and more concerning, Jessica intervenes only to realize Chauncey is much more than the stuffed toy bear she believed him to be.', N'1 Hour 44 Minutes', N'Horror', N'English', N'2', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'70', N'Images\YOLO.png', N'YOLO', '2024-01-26', N'ΓÇ£YOLO" a mainland Chinese comedy film that released in China on the 10th of February; the first day of the Lunar New Year holiday which drew 1.6 billion yuan at the box office in its first four days screening. The film is written, directed by and stars Jia Ling, ChinaΓÇÖs top-grossing female filmmaker. She portrays Le Ying, an unemployed woman in her thirties who still lives with her parents until one day, she meets a boxing coach (portrayed by Lei Jia Ling), who just may change her life.', N'2 Hours 10 Minutes', N'Comedy', N'Mandarin', N'4', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'8', N'Images\Dune.png', N'Dune: Part Two', '2024-02-29', N'With clairvoyant powers that may enable him to guide humanity to a better future, Paul Atreides continues his mythic journey. Now united with Chani and the Fremen, Paul is set on a warpath of revenge against the conspirators who destroyed his family. After taking control of the empire and facing a choice between the love of his life and the fate of the known universe, he endeavours to prevent a terrible future that only he can foresee.', N'2 Hours 46 Minutes', N'Science Fiction', N'English', N'3', 20.0, NULL);
INSERT INTO [dbo].[Movie] ([Id], [Movie], [MovieName], [ReleaseDate], [Description], [DurationTime], [Genre], [Language], [Hall], [Price], [ShowTime]) VALUES (N'9', N'../images/cinema.png', N'Ghostbuster: Frozen Empire', '2024-11-04', N'The Spengler family returns to where it all started - the iconic New York City firehouse - to team up with the original Ghostbusters, who`ve developed a top-secret research lab to take busting ghosts to the next level. But when the discovery of an ancient artifact unleashes an evil force, Ghostbusters new and old must join forces to protect their home and save the world from a second Ice Age.', N'1 Hour 55 Minutes', N'Advanture', N'Chinese', N'1', 20.0, NULL);
